import{_ as s,C as t,o as e,c as r,a3 as l,b as o,w as n,a as m,E as d,a4 as u}from"./chunks/framework.BvvarXmc.js";const g="/screenshots/kelas.png",f=JSON.parse('{"title":"Kelas & Rombel","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-admin/kelas.md","filePath":"panduan-admin/kelas.md","lastUpdated":null}'),k={name:"panduan-admin/kelas.md"};function b(h,a,p,_,c,K){const i=t("Mermaid");return e(),r("div",null,[a[1]||(a[1]=l('<h1 id="kelas-rombel" tabindex="-1">Kelas &amp; Rombel <a class="header-anchor" href="#kelas-rombel" aria-label="Permalink to &quot;Kelas &amp; Rombel&quot;">​</a></h1><p>Menu <strong>Kelas</strong> mengelola struktur rombongan belajar (Rombel), tingkatan kelas, penetapan Wali Kelas, serta daya tampung siswa per ruangan.</p><hr><h2 id="tampilan-manajemen-kelas" tabindex="-1">Tampilan Manajemen Kelas <a class="header-anchor" href="#tampilan-manajemen-kelas" aria-label="Permalink to &quot;Tampilan Manajemen Kelas&quot;">​</a></h2><p><img src="'+g+'" alt="Manajemen Kelas"></p><hr><h2 id="_1-alur-menambah-kelas-rombel-baru" tabindex="-1">1. Alur Menambah Kelas / Rombel Baru <a class="header-anchor" href="#_1-alur-menambah-kelas-rombel-baru" aria-label="Permalink to &quot;1. Alur Menambah Kelas / Rombel Baru&quot;">​</a></h2>',7)),(e(),o(u,null,{default:n(()=>[d(i,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Klik%20'%2B%20Tambah%20Kelas'%22%5D%20--%3E%20B%5B%222.%20Tentukan%20Tingkat%20%26%20Nama%20Rombel%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Tunjuk%20Wali%20Kelas%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Klik%20'Simpan'%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Rombel%20Siap%20Menerima%20Siswa%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Klik tombol <strong><code>+ Tambah Kelas</code></strong> di pojok kanan atas.</li><li>Lengkapi isian formulir: <ul><li><strong>Tingkat Pendidikan</strong>: Pilih tingkat (misal: <em>Kelas 7</em>, <em>Kelas 8</em>, <em>Kelas 9</em> atau <em>X</em>, <em>XI</em>, <em>XII</em>).</li><li><strong>Nama Rombel</strong> <em>(Wajib)</em>: Contoh: <em>7 - AL FUQON</em>, <em>X RPL 1</em>, <em>XI IPA 2</em>.</li><li><strong>Tahun Ajaran Aktif</strong>: Otomatis tertaut pada periode berjalan.</li><li><strong>Wali Kelas</strong>: Pilih nama guru dari daftar dropdown yang ditugaskan membina kelas ini.</li><li><strong>Kapasitas Maksimal</strong>: Batas kuota siswa per kelas (misal: <em>36 siswa</em>).</li></ul></li><li>Klik tombol <strong><code>Simpan Kelas</code></strong>.</li></ol><hr><h2 id="_2-mengubah-data-kelas-mengganti-wali-kelas" tabindex="-1">2. Mengubah Data Kelas &amp; Mengganti Wali Kelas <a class="header-anchor" href="#_2-mengubah-data-kelas-mengganti-wali-kelas" aria-label="Permalink to &quot;2. Mengubah Data Kelas &amp; Mengganti Wali Kelas&quot;">​</a></h2><ol><li>Cari kelas yang ingin disesuaikan pada tabel.</li><li>Klik tombol <strong>Edit</strong>.</li><li>Anda dapat memperbarui nama rombel atau mengganti penugasan Wali Kelas baru.</li><li>Klik <strong><code>Simpan Perubahan</code></strong>. Guru yang baru ditunjuk otomatis akan memiliki akses ke <strong>Dashboard Wali Kelas</strong> untuk rombel tersebut.</li></ol>',5))])}const A=s(k,[["render",b]]);export{f as __pageData,A as default};
